(7, 'joey-redes-sociais', 'Como funciona: redes sociais', 'cliente', 'pt', array['Social Media']::text[], '{"hero": {"eyebrow": "Pouch · Guia do cliente", "title": "Seu calendário de posts, sem caçar mensagem no WhatsApp.", "text": "Este guia mostra como ver o planejamento do mês, aprovar os posts e acompanhar o crescimento do perfil no Pouch."}, "steps": [{"title": "Portal", "who": "Você", "tone": "cliente"}, {"title": "Calendário", "who": "Você", "tone": "cliente"}, {"title": "Aprovar", "who": "Você", "tone": "cliente"}, {"title": "Resultados", "who": "Você", "tone": "cliente"}], "sections": [{"who": "Você", "tone": "cliente", "title": "Seu portal: tudo do seu marketing num lugar só", "text": "Você recebe um link e um login. Pelo celular ou pelo computador, o Pouch mostra o que está esperando você, o que está em produção e o que já foi publicado.", "images": [{"src": "/guias/clientes/joey/home.jpg", "alt": "Tela inicial do portal com o que falta aprovar", "frame": "phone"}, {"src": "/guias/clientes/joey/menu.jpg", "alt": "Menu do portal com todas as áreas", "frame": "phone"}], "layout": "stack", "bullets": ["Na tela inicial, o número laranja é o que está esperando a sua aprovação. Comece sempre por ali.", "O menu (no canto de cima) leva para cada área. Você só vê as áreas do que contratou.", "Salve o link na tela inicial do celular. Fica como um aplicativo."]}, {"who": "Você", "tone": "cliente", "title": "Painel de Conteúdo: o calendário dos seus posts", "text": "Todo post planejado para o mês aparece aqui, com data, formato e situação.", "images": [{"src": "/guias/clientes/joey/conteudo-mapa.jpg", "alt": "Mapa do mês com as legendas de situação", "frame": "phone"}, {"src": "/guias/clientes/joey/conteudo-lista.jpg", "alt": "Lista de posts do mês com a situação de cada um", "frame": "phone"}], "layout": "stack", "bullets": ["As cores dizem a situação: em produção, esperando aprovação, ajustes solicitados, aprovado, programado e publicado.", "Os laranjas são os que esperam você.", "Use as setas para ver o mês seguinte assim que ele for liberado."]}, {"who": "Você", "tone": "cliente", "title": "Aprovar um post", "text": "Toque no post. Você vê exatamente como ele vai ficar no Instagram, com a legenda.", "images": [{"src": "/guias/clientes/joey/post-preview.jpg", "alt": "Prévia do post como vai aparecer no Instagram", "frame": "phone"}, {"src": "/guias/clientes/joey/post-aprovar.jpg", "alt": "Botões Aprovar, Ajuste e Reprovar", "frame": "phone"}], "layout": "stack", "bullets": ["Em Detalhes ficam os botões: Aprovar, Ajuste ou Reprovar.", "Pediu ajuste? Escreva o que mudar nos comentários do post. A conversa fica guardada ali, sem se perder no WhatsApp.", "O histórico mostra cada versão e quem aprovou."]}, {"who": "Você", "tone": "cliente", "title": "Redes sociais: como o perfil está crescendo", "text": "Os números do Instagram são coletados todos os dias e aparecem em Redes Sociais.", "images": [{"src": "/guias/clientes/joey/redes.jpg", "alt": "Painel de redes sociais com alcance, impressões, engajamento e seguidores", "frame": "phone"}], "layout": "image-left", "bullets": ["Alcance: quantas pessoas viram seu conteúdo.", "Engajamento: curtidas, comentários, compartilhamentos e salvos.", "Novos seguidores no período, comparando com o período anterior.", "O gráfico mostra dia a dia o que funcionou melhor."]}, {"who": "Juntos", "tone": "equipe", "dark": true, "title": "O combinado para dar certo", "text": "Quanto mais rápido você responde, mais rápido as coisas vão ao ar. Qualquer dúvida, fale com a Joey pelo WhatsApp.", "cards": [{"title": "Aprove rápido", "text": "O que espera você aparece em laranja na tela inicial."}, {"title": "Mande material", "text": "Fotos e vídeos reais do seu negócio deixam tudo mais forte."}, {"title": "Comente no post", "text": "Ajuste pedido no post não se perde."}]}]}'::jsonb, 1, true),
(7, 'joey-onboarding', 'Como funciona o onboarding de cliente novo na Joey', 'socio', 'pt', '{}'::text[], '{"hero": {"eyebrow": "Pouch · Onboarding de cliente novo na Joey", "title": "Do link de cadastro à campanha no ar, tudo num lugar só.", "text": "É assim que um cliente novo entra na Joey. O cliente faz a parte dele pelo celular, em português, inglês ou espanhol. A gente acompanha tudo num funil no Pouch e o Claude monta a estratégia. Ninguém precisa pedir informação duas vezes nem caçar mensagem no WhatsApp."}, "steps": [{"who": "Sócio", "tone": "equipe", "title": "Link"}, {"who": "Cliente", "tone": "cliente", "title": "Cadastro"}, {"who": "Cliente", "tone": "cliente", "title": "Portal do começo"}, {"who": "Joey", "tone": "equipe", "title": "Funil"}, {"who": "Joey + Claude", "tone": "equipe", "title": "Estratégia"}, {"who": "Cliente", "tone": "cliente", "title": "Aprovação"}, {"who": "Joey", "tone": "equipe", "title": "No ar"}], "sections": [{"who": "Sócio", "tone": "equipe", "title": "Cada sócio tem o próprio link de cadastro", "text": "Fechou com o cliente? Mande o seu link de cadastro pelo WhatsApp. Ele fica em Comercial › Onboarding, no botão Copiar link de cadastro, e abre em pouch.joeygrowth.com.", "bullets": ["O cliente fica marcado como trazido por quem mandou o link. Isso vale para a comissão.", "No fim do cadastro, o botão de contato abre o WhatsApp de quem trouxe o cliente.", "O cadastro salva a cada passo. Se o cliente parar no meio, o funil mostra onde ele parou."]}, {"who": "Cliente", "tone": "cliente", "title": "Cadastro em 5 passos, pelo celular, em uns 5 minutos", "layout": "stack", "text": "O cliente escolhe o idioma e pode trocar a qualquer momento no topo. Valores aparecem em US$.", "cards": [{"title": "Idioma", "text": "Português, inglês ou espanhol."}, {"title": "Dados", "text": "Nome, empresa, e-mail de acesso, WhatsApp, site e Instagram."}, {"title": "Negócio", "text": "Serviços contratados, o que vende, ticket, região, público, verba e o que já tentou."}, {"title": "Acessos", "text": "Passo a passo do Meta e do Google. Travou? Marca \"Preciso de ajuda\" e a equipe é avisada."}, {"title": "Termos", "text": "Termos do serviço com o nome da empresa e do responsável."}, {"title": "Senha", "text": "Cria o login e entra direto no portal."}], "images": [{"src": "/guias/joey/onboarding/02-cadastro-idioma.jpg", "alt": "Escolha de idioma do cadastro da Joey", "frame": "phone"}, {"src": "/guias/joey/onboarding/03-cadastro-dados-en.jpg", "alt": "Passo 1 do cadastro, em inglês", "frame": "phone"}, {"src": "/guias/joey/onboarding/04-cadastro-negocio.jpg", "alt": "Passo 2 do cadastro: negócio", "frame": "phone"}, {"src": "/guias/joey/onboarding/05-cadastro-acessos.jpg", "alt": "Passo 3 do cadastro: acessos com passo a passo do Meta", "frame": "phone"}, {"src": "/guias/joey/onboarding/06-cadastro-termos.jpg", "alt": "Passo 4 do cadastro: termos do serviço", "frame": "phone"}]}, {"who": "Cliente", "tone": "cliente", "title": "O portal mostra onde estamos e o que falta", "layout": "image-left", "images": [{"src": "/guias/joey/onboarding/07-portal-cliente.jpg", "alt": "Portal do cliente com as etapas do começo do trabalho", "frame": "phone"}], "bullets": ["Seis etapas sempre à vista: Cadastro, Briefing, Acessos, Estratégia, Aprovação e No ar.", "Um cartão escuro diz qual é o próximo passo do cliente, por exemplo responder o briefing de tráfego.", "Os acessos ficam com o mesmo passo a passo do cadastro. Quando o cliente marca \"Já enviei\", a equipe confere e o selo muda para Conferido.", "Quando a estratégia fica pronta, o topo muda para \"Sua estratégia está pronta para você aprovar\"."]}, {"who": "Joey", "tone": "equipe", "dark": true, "title": "Um funil que diz o que a equipe precisa fazer agora", "layout": "stack", "text": "Em Comercial › Onboarding, cada cliente novo aparece numa coluna. As colunas mostram com quem está a bola. O menu ganha um número vermelho com quantos clientes estão esperando a equipe.", "images": [{"src": "/guias/joey/onboarding/12-funil.jpg", "alt": "Funil de novos clientes da Joey", "frame": "browser"}], "bullets": ["No topo: quantos precisam da equipe, quantos estão com o cliente, quantos foram ao ar e a média de dias do cadastro ao ar.", "Cada cartão mostra o próximo passo: Gerar a estratégia, Ajudar com Google, Conferir acesso Meta, Ajustar a estratégia, Colocar a campanha no ar.", "Pedido de ajuda nos acessos vira um alerta amarelo com o nome do cliente."]}, {"who": "Joey + Claude", "tone": "equipe", "title": "O Claude monta a estratégia. A equipe revisa e envia.", "images": [{"src": "/guias/joey/onboarding/13-ficha.jpg", "alt": "Ficha do cliente: acessos conferidos e estratégia enviada", "frame": "browser"}], "bullets": ["\"Gerar estratégia com o Claude\" lê o cadastro e o briefing e escreve o plano, no idioma que o cliente escolheu e em US$.", "Também lista pontos em aberto só para a equipe.", "Precisa mudar? \"Pedir ajuste ao Claude\" com uma frase. Ele gera uma nova versão mudando só o que foi pedido, e as anteriores ficam guardadas.", "\"Copiar link e mensagem\" já prepara o texto para o WhatsApp do cliente."]}, {"who": "Cliente", "tone": "cliente", "title": "O cliente lê, aprova ou pede ajuste pela própria página", "layout": "stack", "text": "A estratégia chega como uma página feita para o celular, escrita para o dono do negócio, sem jargão.", "images": [{"src": "/guias/joey/onboarding/09-estrategia-topo.jpg", "alt": "Topo da página da estratégia", "frame": "phone"}, {"src": "/guias/joey/onboarding/10-estrategia-verba.jpg", "alt": "Campanhas e divisão da verba", "frame": "phone"}, {"src": "/guias/joey/onboarding/11-estrategia-aprovar.jpg", "alt": "Botões para aprovar ou pedir ajuste", "frame": "phone"}], "bullets": ["A equipe vê se ele abriu, quantas vezes e por quanto tempo leu.", "\"Quero ajustar algo\": o pedido cai no funil em amarelo e o Claude gera a versão seguinte a partir dele.", "O link é sempre o mesmo e mostra a versão mais recente.", "\"Aprovar estratégia\" registra quem aprovou e quando. O cartão vai para Subir campanha."]}, {"who": "Joey", "tone": "equipe", "title": "Campanha no ar, cliente ativo", "text": "Com as campanhas configuradas, a equipe clica em \"Campanha no ar\". O cliente passa a ser ativo e o portal dele vira o portal normal: tráfego, CRM, criativos, conteúdo e relatórios.", "cards": [{"title": "O cliente faz", "text": "Cadastro, briefing, acessos e aprovação. Tudo pelo celular, no idioma dele."}, {"title": "A Joey faz", "text": "Mandar o link, conferir acessos, revisar e enviar a estratégia e subir a campanha."}]}]}'::jsonb, 1, true);
